using System.Collections;
using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

public class PurifyCorruptWithMultiplierActions : BattleAction
{
	[Header("Purify")]
	[SerializeField]
	protected BattleAction purifyCorruptAction;

	[SerializeField]
	private bool fixedPurifyMultiplier;

	[SerializeField]
	[ShowIf("fixedPurifyMultiplier")]
	private int purifyMultiplier;

	[SerializeField]
	private bool enableBasePurifyAmount;

	[SerializeField]
	[ShowIf("enableBasePurifyAmount")]
	private int basePurifyAmount;

	[SerializeField]
	[ShowIf("enableBasePurifyAmount")]
	private bool multiplyByBase;

	[SerializeField]
	private bool ignoreForEachOnDescription;

	[SerializeField]
	private bool ignoreCheckConditionToBeCasted;

	[Header("VFX")]
	[SerializeField]
	protected bool enableVFXDelay;

	[SerializeField]
	[ShowIf("enableVFXDelay")]
	protected float vfxDelay;

	[SerializeField]
	private bool vfxOnSource;

	public BattleAction PurifyCorruptAction => purifyCorruptAction;

	public bool FixedPurifyMultiplier => fixedPurifyMultiplier;

	public int PurifyMultiplier => purifyMultiplier;

	public bool EnableBasePurifyAmount => enableBasePurifyAmount;

	public int BasePurifyAmount => basePurifyAmount;

	public bool IgnoreForEachOnDescription => ignoreForEachOnDescription;

	public override bool CheckConditionToBeCasted(int actionValue)
	{
		if (ignoreCheckConditionToBeCasted)
		{
			return true;
		}
		return PurifyAmount(actionValue, checkConditionToBeCastedOrPreview: true) > 0;
	}

	public virtual int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return 0;
	}

	public virtual int PurifyAmount(int amount, bool checkConditionToBeCastedOrPreview = false)
	{
		if (!base.isOnBattleScene)
		{
			return 0;
		}
		int num = (fixedPurifyMultiplier ? PurifyMultiplier : amount);
		int num2 = (enableBasePurifyAmount ? basePurifyAmount : 0);
		int num3 = 0;
		if (multiplyByBase)
		{
			num3 = num2 * PurifyCounter(checkConditionToBeCastedOrPreview) * num;
			if (num3 == 0)
			{
				num3 = num2;
			}
		}
		else
		{
			num3 = num2 + PurifyCounter(checkConditionToBeCastedOrPreview) * num;
		}
		return num3;
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && enableVFXDelay)
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetAmountVFXDelay(target, amount, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
			return;
		}
		BeforePurify(source);
		SpawnVFX(GetVFXOwnerPosition(vfxOnSource ? source : target), 6f);
		SpawnSecondVFX(6f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		DefaultSingleTargetCast(target, amount, source);
	}

	private IEnumerator CastTargetAmountVFXDelay(GameObject target, int amount, GameObject source)
	{
		BeforePurify(source);
		SpawnVFX(GetVFXOwnerPosition(vfxOnSource ? source : target), 6f);
		SpawnSecondVFX(6f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		yield return new WaitForSeconds(vfxDelay);
		DefaultSingleTargetCast(target, amount, source);
	}

	private void DefaultSingleTargetCast(GameObject target, int amount, GameObject source)
	{
		purifyCorruptAction.CastTargetAmount(target, PurifyAmount(amount), source);
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		AfterPurify(source);
	}

	protected virtual void BeforePurify(GameObject source)
	{
	}

	protected virtual void AfterPurify(GameObject source)
	{
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		CastTargetAmount(target, PurifyAmount(0), source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		purifyCorruptAction.AreaCastTargetAmount(targets, PurifyAmount(amount), source);
		if (vfxOnSource)
		{
			SpawnVFX(GetVFXOwnerPosition(source), 6f);
		}
		else
		{
			for (int i = 0; i < targets.Count; i++)
			{
				SpawnVFX(GetVFXOwnerPosition(targets[i]), 6f);
			}
		}
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		AfterPurify(source);
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		AreaCastTargetAmount(targets, PurifyAmount(0), source);
	}

	public override void Cast(GameObject source)
	{
		purifyCorruptAction.CastAmount(PurifyAmount(0), source);
		AfterPurify(source);
	}

	public override void CastAmount(int amount, GameObject source)
	{
		purifyCorruptAction.CastAmount(amount, source);
		AfterPurify(source);
	}
}
